    "content": "一、“茆港”“红豆”牵姻缘 《柳如是别传·缘起》开篇，陈寅恪写道：“寅恪以衰废余年……购得常熟白茆港钱氏故园中红豆一粒，乃笺释钱柳因缘。”此处地名“白茆港”作为常熟地名，保留了晚明江南文献特有的用字习惯。 《红楼梦旨义》作者自又云“今日一事无成……虽今日之茆椽……”。后世多将此处的“茆椽”擅改为“茅椽”，但原文固定作“茆椽”，并非抄写讹误，而是作者主动选择的用字。这种用字层面的高度重合，在文本比较中具有强关联性，绝非偶然。 “茆”字的深层意涵不止一层，而是双层累叠。 第一层是表层含义通“茅”：清贫隐逸，疏离官宦。《…"
