    "content": "新华社纽约8月20日电 纽约股市三大股指20日显著下跌。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌703.84点，收于52759.21点，跌幅为1.32%；标准普尔500种股票指数下跌66.82点，收于7641.16点，跌幅为0.87%；纳斯达克综合指数下跌263.92点，收于26067.17点，跌幅为1.00%。 板块方面，标普500指数十一大板块九跌二涨。必需消费品板块和医疗板块分别以1.93%和1.89%的跌幅领跌，能源板块和房地产板块分别上涨0.38%和0.15%。"
