    "content": "如果你也曾撅着屁股在草地上找过四叶草，那你一定对这个全世界通用的幸运符号并不陌生。但如果你至今还没找到幸运四叶草，不妨换个思路，抬头找找六瓣的鸡蛋花。 罕见的六瓣鸡蛋花和普通的五瓣鸡蛋花 | 幸运的编辑 要知道，四叶草的变异率大约是五千分之一。而五瓣的鸡蛋花多长一片花瓣这种事，都还没能形成统计。《中国植物志》里对鸡蛋花属的描述是花冠5裂，对所属夹竹桃科的描述则是5裂、稀4裂，6裂从未被提及。六瓣的鸡蛋花，可能比四叶草还稀罕，还要幸运。 但，这多出来的一片花瓣，到底是打哪儿来的？ 一枚雄蕊的cosplay首秀 很早以…"
