    "content": "8月20日，瑞士联邦主席兼经济、教研部长帕姆兰在伯尔尼会见商务部部长王文涛，共同宣布完成中国—瑞士自由贸易协定升级谈判并签署谅解备忘录。中国驻瑞士大使钱敏坚、瑞士驻华大使马婷等出席活动。 王文涛表示，2026年1月，习近平主席向帕姆兰主席致贺电，强调中方愿与瑞方一道努力，持续扩大互利合作，推动中瑞关系不断迈上新台阶。2024年9月，中瑞双方启动自贸协定升级谈判，在双方共同努力下，历经五轮磋商，升级谈判成功完成。双方承诺将在货物、服务、投资、规则等多个领域作出更高水平双向开放，这将为两国经贸合作创造新的机遇。瑞士是中…"
