    "description": "新华社俄罗斯摩尔曼斯克8月20日电（记者许炜凯 郝建伟）俄罗斯摩尔曼斯克海上贸易港20日举行首艘中国集装箱船靠港欢迎仪式，庆祝该港首条来自中国的集装箱航线顺利开通。这标志着通过北极航道连接中国沿海港口与俄北极圈内最大深水港的定期货物运输业务正式拉开序幕。 中国驻圣彼得堡总领事罗占辉代读中国驻俄罗斯大使张汉晖致本次欢迎仪式的贺信。贺信指出，中国企业旗下集装箱船经北极航道顺利抵达摩尔曼斯克港，这是中俄深化北极合作的最新成果，也是“冰上丝绸之…",
    "content": "新华社俄罗斯摩尔曼斯克8月20日电（记者许炜凯 郝建伟）俄罗斯摩尔曼斯克海上贸易港20日举行首艘中国集装箱船靠港欢迎仪式，庆祝该港首条来自中国的集装箱航线顺利开通。这标志着通过北极航道连接中国沿海港口与俄北极圈内最大深水港的定期货物运输业务正式拉开序幕。 中国驻圣彼得堡总领事罗占辉代读中国驻俄罗斯大使张汉晖致本次欢迎仪式的贺信。贺信指出，中国企业旗下集装箱船经北极航道顺利抵达摩尔曼斯克港，这是中俄深化北极合作的最新成果，也是“冰上丝绸之路”从愿景走向现实的生动实践。摩尔曼斯克是俄破冰船队母港和北极航道最大转运节点，…"
