    "description": "新华社伦敦/巴黎8月20日电（记者于艾岑 孙毅）英国、法国、德国、意大利、荷兰、挪威和加拿大20日发表联合声明，谴责以色列“E1区”定居点建设计划，并敦促以政府立即撤回该计划。 七国在声明中表示，以色列政府公布“E1区”定居点建设项目招标决定“不可接受”，该项目将割裂约旦河西岸，损害巴勒斯坦领土的连续性，破坏“两国方案”前景。 声明强调，国际法明确认定以色列在约旦河西岸的定居点非法，这是国际社会的立场，并得到联合国安理会支持。 声明指出…",
    "content": "新华社伦敦/巴黎8月20日电（记者于艾岑 孙毅）英国、法国、德国、意大利、荷兰、挪威和加拿大20日发表联合声明，谴责以色列“E1区”定居点建设计划，并敦促以政府立即撤回该计划。 七国在声明中表示，以色列政府公布“E1区”定居点建设项目招标决定“不可接受”，该项目将割裂约旦河西岸，损害巴勒斯坦领土的连续性，破坏“两国方案”前景。 声明强调，国际法明确认定以色列在约旦河西岸的定居点非法，这是国际社会的立场，并得到联合国安理会支持。 声明指出，当前约旦河西岸局势动荡不安，定居者针对平民的暴力达到前所未有的程度，巴勒斯坦经…"
