    "content": "Getty Images / 巴拿马运河约占全球海运贸易量5%，但美国近40%的集装箱运输都经过这里。 随着伊朗战争持续干扰全球其中一条最重要的航运通道霍尔木兹海峡，数千公里以外另一个战略咽喉也成为新的角力焦点，那就是连接大西洋与太平洋的重要通道——巴拿马运河。 最新一轮交锋上周在联合国上演。美国警告，中国在巴拿马运河周边的影响力日益扩大，可能威胁全球贸易和安全。 北京驳斥这项说法，指责华盛顿以此为藉口，企图扩大对运河的控制。 夹在两国之间的巴拿马则重申对运河拥有主权，并强调运河将永久保持中立。 巴拿马运河是甚么？…"
