    "content": "当地时间8月20日，法国、德国、意大利、挪威、荷兰和英国领导人发表联合声明，称以色列政府决定就约旦河西岸“E1区”定居点项目发布建设招标“不可接受”，敦促以方立即撤回相关项目，并停止扩大约旦河西岸定居点。 约旦河西岸犹太人定居点（资料图） 声明称，“E1区”定居点项目将把约旦河西岸进一步分割，破坏巴勒斯坦领土的连续性，损害“两国方案”的前景。声明重申，以色列在约旦河西岸的定居点违反国际法。 六国领导人同时呼吁企业不要参与相关建设项目投标，并警告企业应充分考虑可能面临的法律和声誉风险，包括成为严重违反国际法行为共犯的…"
