    "content": "中国电影《给阿嬷的情书》20日在缅甸仰光首映，中缅两国各界人士200余人观影。 新华社仰光8月20日电（记者张东强）中国电影《给阿嬷的情书》20日在缅甸仰光首映，中缅两国各界人士200余人观影。 这部影片以潮汕方言为主，围绕“侨批”主线，讲述老一辈华侨下南洋谋生时与家乡亲人彼此牵挂、守望相助的故事。集华侨家书和汇款凭证同体的“银信合封”被称为“侨批”，是上个世纪南洋华侨与故乡通信的主要方式。 缅甸女演员雍温拉昂观影后对记者说，影片没有大起大落的剧情，却能触动人心，片尾段落让人喜极而泣。 缅甸东方学校荣誉董事长曾圆香…"
