    "description": "20/08/2026 - 18:10 共同社8月20日电：在日本御宅文化扎根的中国上海市，限制地下偶像现场演唱日语歌的动向正在扩大。 有业内相关人士认为，这可能是当地有关部门揣度中央政府对日政策而做出的表现。随着日中关系恶化，在中国还出现了活动中限制角色扮演 Cosplay日本动漫角色等情况，“御宅族叫苦不迭”的日子持续。 据小剧场Live House相关人士透露，自今年7月以来，上海市多个区的当地有关部门口头指示不得在舞台上演唱包含日…",
    "content": "20/08/2026 - 18:10 共同社8月20日电：在日本御宅文化扎根的中国上海市，限制地下偶像现场演唱日语歌的动向正在扩大。 有业内相关人士认为，这可能是当地有关部门揣度中央政府对日政策而做出的表现。随着日中关系恶化，在中国还出现了活动中限制角色扮演 Cosplay日本动漫角色等情况，“御宅族叫苦不迭”的日子持续。 据小剧场Live House相关人士透露，自今年7月以来，上海市多个区的当地有关部门口头指示不得在舞台上演唱包含日语歌词的歌曲。在中国进行现场演出必须事先向有关部门提交曲名和歌词接受审查，但7月…"
