    "description": "美国总统特朗普20日在社交媒体发文，宣布白宫立法事务主任詹姆斯·布雷德将于9月离职。 新华社华盛顿8月20日电 美国总统特朗普20日在社交媒体发文，宣布白宫立法事务主任詹姆斯·布雷德将于9月离职。 另据报道，布雷德是白宫负责与国会联络的高级助理。 布雷德是近期即将离职的又一位白宫助理。特朗普12日宣布白宫新闻秘书卡罗琳·莱维特将于8月底辞职，以腾出更多时间陪伴家人。",
