    "content": "新华社塔什干8月20日电（记者包诺敏）在乌兹别克斯坦，抓饭不仅是一道食物，更承载着家庭传统、待客之道与情感认同。从日常三餐到盛大婚礼与节庆活动，抓饭串联起当地民众的岁月点滴与人生重要时刻。 这是2024年8月27日在乌兹别克斯坦首都塔什干拍摄的抓饭。新华社记者曹阳摄 丝路上的融合美食 乌兹别克斯坦抓饭的确切出现时间已不可考。这里一种流传的说法是，抓饭由中世纪波斯哲学家、医学家伊本·西那发明，当时用七种食材烹制：洋葱、胡萝卜、肉、油、盐、水和米饭，这些食材的单词首字母拼在一起就是抓饭名称。 另一种说法是，抓饭起源于亚…"
