    "content": "新华社加德满都8月20日电（记者张平）尼泊尔流行病与疾病控制局发布的最新数据显示，截至8月15日，该国77个县中有74个县报告了登革热病例，累计报告病例2844例。今年以来，该国已报告两例登革热相关死亡病例。 尼泊尔卫生部门日前警告说，登革热疫情已几乎蔓延至全国，随着雨季后期的到来，感染病例可能进一步增多。 尼泊尔流行病与疾病控制局7月中旬启动了一项为期3个月的登革热宣传教育活动，活动主题为“小叮咬，大挑战”，重点聚焦定期监测和清理蚊虫孳生地。 据该机构介绍，全球已报告的蚊子种类超过3500种，尼泊尔迄今已鉴定出1…"
