    "content": "IT之家 8 月 20 日消息，在今天（20 日）晚间的分析师电话会上，阿里 CEO 吴泳铭透露，平头哥第二代国产芯片预计今年下半年开始流片、产出，这一代的芯片将具有 “非常强”的算力和互联带宽 ，内部认为“完全可以”替代大规模模型训练。 同时，基于新一代平头哥芯片真武 M890 的超节点实例，近日已上线阿里云进行规模化销售，下半年 将持续放量 以满足客户的旺盛需求。今天早些时候，阿里公布的财报披露，平头哥已建立 覆盖 GPU、CPU、网络芯片 的全栈自研芯片组合，真武芯片到 8 月初已经服务了超过 650 家客户…"
