    "content": "社会人士张龙冒充“香港中文大学客座教授”被校方公开声明打假后，其精心包装的人设相继被戳穿。 澎湃新闻记者注意到，今年稍早前，张龙曾在个人认证的微博账号上妄称自己是电影《给阿嬷的情书》主题曲作者。这一身份如今也被证实为虚假。 今年6月，张龙在微博发布了一首歌曲的MV，并且声称：“以歌作信，遥念阿嬷｜资深传媒人、原创音乐人、 著名文化学者张龙力作，为电影《给阿嬷的情书》写主题曲《侨批寄流年》，一纸侨批，半生思念，唱尽山海乡愁。” 2026年8月20日晚间，澎湃新闻记者从权威渠道确认，张龙既不是电影《给阿嬷的情书》主题曲…"
