    "content": "中新网8月20日电 据“辽阳市第三人民医院 妇幼保健院”微信公众号消息，辽阳市第三人民医院20日晚发布一则情况通报称，近日，媒体报道“孕妇产检因医生疏忽误服有毒液体”事件引发社会关注。8月7日，孕妇朱某某到辽阳市第三人民医院产科门诊进行糖耐量筛查产检，由于接诊医生将新柏氏细胞保存液与筛查所用的口服葡萄糖粉混放存放、现场核对不严、宣教指导流程落实不到位，院内制度执行不严格，导致朱某某误服新柏氏细胞保存液。朱某某发现误服后，立即告知医生，辽阳市第三人民医院马上组织专家团队开展多学科会诊和母胎监护，并收入院治疗。经国内权…"
