    "description": "欧盟一般不限制AI能生成什么，但要求生成内容如实交代“来历”。人机之间那条过去全凭企业自觉的界线，如今将由法律来重新划定。 南方防务智库特约研究员 金耀 责任编辑：姚忆江 据新华社报道，2026年8月2日起，欧盟《人工智能法案》规定的透明度义务条款正式生效。 此前7月20日，欧盟委员会发布《特定人工智能系统透明度义务实施指南》（以下简称《指南》），为《人工智能法案》第50条的落地划定了操作标准。根据上述法规要求，欧盟境内所有与人对话的A…",
    "content": "欧盟一般不限制AI能生成什么，但要求生成内容如实交代“来历”。人机之间那条过去全凭企业自觉的界线，如今将由法律来重新划定。 南方防务智库特约研究员 金耀 责任编辑：姚忆江 据新华社报道，2026年8月2日起，欧盟《人工智能法案》规定的透明度义务条款正式生效。 此前7月20日，欧盟委员会发布《特定人工智能系统透明度义务实施指南》（以下简称《指南》），为《人工智能法案》第50条的落地划定了操作标准。根据上述法规要求，欧盟境内所有与人对话的AI，原则上必须主动表明机器身份，AI生成的内容必须带上标识。 由此，深夜直播间里…"
