    "description": "第二届《四部医典》暨曼唐研究国际学术研讨会现场（8月20日摄）。新华社记者 旦增尼玛曲珠 摄 新华社拉萨8月20日电（记者刘洲鹏、旦增尼玛曲珠）第二届《四部医典》暨曼唐研究国际学术研讨会20日在西藏拉萨举办，来自中国、英国、德国、奥地利、蒙古国以及尼泊尔等国的200余名专家学者围绕藏医药学的历史溯源、理论体系、活态传承、保护利用等议题开展深度研讨。与会专家认为，藏医药在国际舞台的应用日渐广泛。 《四部医典》是藏医药学奠基著作，构筑了完整…",
    "content": "第二届《四部医典》暨曼唐研究国际学术研讨会现场（8月20日摄）。新华社记者 旦增尼玛曲珠 摄 新华社拉萨8月20日电（记者刘洲鹏、旦增尼玛曲珠）第二届《四部医典》暨曼唐研究国际学术研讨会20日在西藏拉萨举办，来自中国、英国、德国、奥地利、蒙古国以及尼泊尔等国的200余名专家学者围绕藏医药学的历史溯源、理论体系、活态传承、保护利用等议题开展深度研讨。与会专家认为，藏医药在国际舞台的应用日渐广泛。 《四部医典》是藏医药学奠基著作，构筑了完整系统的藏医学理论体系，是中华民族传统医药文化的璀璨瑰宝。曼唐是藏医药可视化医学教…"
