    "pub_date": "2026-08-20 21:41:35",
    "author": "",
    "description": "中新社福州8月20日电 (叶秋云)福建省人民政府官网20日发布福建省人民政府关于印发《福建省“十五五”文化和旅游发展规划》(以下简称“规划”)的通知及规划政策解读。规划提及“深化闽台交流，探索两岸文旅融合发展新路径”，提出鼓励台湾同胞申报国家级、省级、市级、县级非遗代表性传承人。",
    "content": "中新社福州8月20日电 (叶秋云)福建省人民政府官网20日发布福建省人民政府关于印发《福建省“十五五”文化和旅游发展规划》(以下简称“规划”)的通知及规划政策解读。规划提及“深化闽台交流，探索两岸文旅融合发展新路径”，提出鼓励台湾同胞申报国家级、省级、市级、县级非遗代表性传承人。"
