    "description": "中新网昆山8月20日电 (记者 钟升)据江苏省昆山市台办20日消息，台胞住房公积金跨境直付业务已于近日在当地落地。在苏州市住房公积金管理中心昆山分中心“台胞台企服务专窗”，大陆住房公积金可直接划转至台湾地区个人银行账户。这一举措在大陆尚属首次。",
    "content": "中新网昆山8月20日电 (记者 钟升)据江苏省昆山市台办20日消息，台胞住房公积金跨境直付业务已于近日在当地落地。在苏州市住房公积金管理中心昆山分中心“台胞台企服务专窗”，大陆住房公积金可直接划转至台湾地区个人银行账户。这一举措在大陆尚属首次。"
