    "content": "一块“生态伤疤”如何蝶变为城市新名片？近日，新华社记者跟随“活力中国调研行”采访团来到福建省漳州市，行走西溪江畔，感受当地还江于民、兴水利民的建设成效。 这是8月19日拍摄的漳州龙江岁月园区一角。新华社记者 林善传 摄 傍晚时分，江风徐徐、热气稍减，漳州市西溪南岸的龙江岁月园区里逐渐热闹了起来。临河慢道上，一群群市民游客散步、骑行；红砖古厝风格的咖啡馆里，年轻人围坐闲聊；展馆“尚书堂”里，许多人驻足了解漳州的文脉传承。 九龙江是漳州的母亲河，穿城而过的西溪是九龙江的重要支流。过去长期一段时间，西溪部分区域不仅发展滞…"
