    "content": "新华社达卡8月20日电 孟加拉国20日举行总统选举，执政党孟加拉国民族主义党候选人米尔扎·法赫尔·伊斯兰·阿拉姆吉尔当选孟加拉国第23任总统。 8月20日，在孟加拉国首都达卡的国民议会大厦，米尔扎·法赫尔·伊斯兰·阿拉姆吉尔（左）在总统选举结束后接受祝贺。 新华社发 根据孟加拉国选举委员会当天公布的结果，阿拉姆吉尔获得255票，孟加拉国伊斯兰大会党领导的联盟提名的候选人奥利·艾哈迈德获得88票。 孟加拉国总统由议会议员选举产生。当天的投票于当地时间14时至17时在孟加拉国首都达卡的国民议会大厦举行，共有349名议员…"
