    "content": "新华社洛杉矶8月19日电（记者谭晶晶）美国制药企业默沙东公司和生物技术企业莫德纳公司19日宣布，双方联合研发的一种基于mRNA（信使核糖核酸）技术的个体化新抗原疗法，与一种免疫治疗药物联合使用，在针对高危黑色素瘤切除术后预防复发3期临床试验中取得积极结果。 黑色素瘤是一种起源于皮肤色素生成细胞（黑色素细胞）的皮肤癌，也是最具侵袭性和危险性的皮肤癌。根据两家公司发布的新闻公报，个体化新抗原疗法针对每名黑色素瘤患者肿瘤中独特的突变组合量身定制，旨在训练并激活免疫系统以识别并攻击癌细胞。联合使用的免疫治疗药物帕博利珠单抗…"
