    "content": "新华社香港8月20日电 在港上市的阿里巴巴集团20日发布2027财年第一季度财报，本季度收入同比增长9%至2689.5亿元，AI商业化全面加速。 阿里巴巴财报显示，本季度“阿里云”外部商业化收入同比增长45%，增速创22个季度新高；AI相关产品季度收入达123.76亿元，连续第12个季度实现三位数同比增长。AI云与算力服务分部经调整EBITA同比大增133%，利润率升至12%。 阿里巴巴集团首席执行官吴泳铭表示，得益于“全栈AI战略”，阿里巴巴处于非常有利的地位，可以把握人工智能和AI算力市场的巨大增长机遇。 财报…"
