    "description": "《全民医疗保障“十五五”规划》19日正式发布，擘画了未来5年医保事业发展的蓝图。这份规划里，除了对制度框架的宏观铺排、改革方向的部署，还专门设置5个民生实事专栏。灵活就业者怎么参保？半夜发烧去哪家药店能买到药？手机上能不能看到就诊排到几号了？这些让群众皱眉头的问题，被正式写进了顶层设计的任务单，也让人感慨，大规划里也有“小确幸”。",
