    "description": "选拔制度的公正性，不仅关乎人才配置的效率，更关乎社会的稳定。 李井奎 责任编辑：顾策 公元1033年的一天，北宋朝廷发布了一道旨意：在地方科举考试中实行“糊名”制度。考生的姓名、籍贯等个人信息被遮盖起来，考官在阅卷时无法知道卷子是谁答的。 四年后的1037年，又加了一道“誊录”制度：考生的答卷被专人重新抄写一遍再交给考官，连笔迹都被抹去了。 到了1044—1045年间，更激进的制度来了：地方官员推荐候选人的权力被彻底废除。在此之前，即使…",
    "content": "选拔制度的公正性，不仅关乎人才配置的效率，更关乎社会的稳定。 李井奎 责任编辑：顾策 公元1033年的一天，北宋朝廷发布了一道旨意：在地方科举考试中实行“糊名”制度。考生的姓名、籍贯等个人信息被遮盖起来，考官在阅卷时无法知道卷子是谁答的。 四年后的1037年，又加了一道“誊录”制度：考生的答卷被专人重新抄写一遍再交给考官，连笔迹都被抹去了。 到了1044—1045年间，更激进的制度来了：地方官员推荐候选人的权力被彻底废除。在此之前，即使考生的答卷被糊名了，地方长官仍然可以凭借“推荐权”把自己看中的人直接塞进通过名单…"
